const KEY='codesinfo-radar-v1';
const baseSources=[{name:'Prefeitura do Cabo',url:'https://www.cabo.pe.gov.br/'},{name:'Câmara Municipal',url:'https://www.cabodesantoagostinho.pe.leg.br/'},{name:'SAPL · atividade legislativa',url:'https://sapl.cabodesantoagostinho.pe.leg.br/'}];
let data={pitches:[],sources:baseSources}, persistence=true;
try{const saved=JSON.parse(localStorage.getItem(KEY));if(saved&&Array.isArray(saved.pitches)&&Array.isArray(saved.sources))data=saved}catch{persistence=false}
const $=id=>document.getElementById(id), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const safeUrl=s=>{try{const u=new URL(s);return ['https:','http:'].includes(u.protocol)?u.href:''}catch{return ''}};
function toast(s){$('toast').textContent=s;$('toast').hidden=false;setTimeout(()=>$('toast').hidden=true,4500)}
function save(){try{localStorage.setItem(KEY,JSON.stringify(data));return true}catch{persistence=false;toast('Não foi possível salvar no navegador. Exporte uma cópia agora.');return false}}
function tab(id){['board','new','sources'].forEach(t=>$(t).hidden=t!==id);document.querySelectorAll('[data-tab]').forEach(b=>b.classList.toggle('active',b.dataset.tab===id));if(id==='new'&&!$('editId').value)$('date').value=new Date().toLocaleDateString('en-CA')}
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{if(b.dataset.tab==='new')reset();tab(b.dataset.tab)});
function reset(){$('pitchForm').reset();$('editId').value='';$('formTitle').textContent='Nova ficha de pauta';$('date').value=new Date().toISOString().slice(0,10)}
const fields=['title','topic','source','url','date','status','facts','interest','angle','questions'];
function render(){const query=$('query').value.toLocaleLowerCase('pt-BR'),status=$('filter').value;const items=data.pitches.filter(p=>(!status||p.status===status)&&JSON.stringify(p).toLocaleLowerCase('pt-BR').includes(query));$('total').textContent=data.pitches.length;$('cards').innerHTML=items.length?items.map(p=>`<article><div class="meta">${esc(p.date)} · ${esc(p.status)}</div><h3>${esc(p.title)}</h3><span class="tag">${esc(p.topic)}</span>${p.demo?'<span class="tag">Exemplo fictício</span>':''}<p>${esc(p.facts).slice(0,240)}</p><p class="small">Fonte: ${esc(p.source)} ${safeUrl(p.url)?`<a href="${esc(safeUrl(p.url))}" target="_blank" rel="noopener noreferrer">Abrir ↗</a>`:''}</p><details><summary>Ver ficha completa</summary><h4>Interesse público</h4><p>${esc(p.interest)||'A preencher'}</p><h4>Hipótese a confirmar</h4><p>${esc(p.angle)||'A preencher'}</p><h4>Perguntas de apuração</h4><pre>${esc(p.questions)||'A preencher'}</pre></details><div class="toolbar"><button data-edit="${esc(p.id)}">Editar</button><button data-copy="${esc(p.id)}">Copiar ficha</button><button data-delete="${esc(p.id)}">Excluir</button></div></article>`).join(''):'<div class="empty"><h3>Nenhuma pauta por aqui.</h3><p>Comece com uma informação e sua fonte.</p><button id="emptyNew">Criar primeira pauta</button></div>';$('emptyNew')?.addEventListener('click',()=>{reset();tab('new')});$('sourceCards').innerHTML=data.sources.map(s=>`<article><h3>${esc(s.name)}</h3><a class="button" href="${esc(safeUrl(s.url))}" target="_blank" rel="noopener noreferrer">Consultar fonte ↗</a></article>`).join('')}
$('pitchForm').onsubmit=e=>{e.preventDefault();if($('url').value&&!safeUrl($('url').value)){toast('Use um endereço http ou https.');return}const id=$('editId').value||crypto.randomUUID();const old=data.pitches.find(p=>p.id===id);const pitch={id,...Object.fromEntries(fields.map(f=>[f,$(f).value.trim()])),demo:old?.demo||false};data.pitches=data.pitches.filter(p=>p.id!==id);data.pitches.unshift(pitch);const persisted=save();reset();render();tab('board');if(persisted)toast('Ficha salva neste navegador.')};
$('cards').onclick=async e=>{const b=e.target.closest('button');if(!b)return;const id=b.dataset.edit||b.dataset.delete||b.dataset.copy,p=data.pitches.find(p=>p.id===id);if(!p)return;if(b.dataset.edit){fields.forEach(f=>$(f).value=p[f]||'');$('editId').value=id;$('formTitle').textContent='Editar ficha de pauta';tab('new')}if(b.dataset.delete&&confirm('Excluir esta ficha deste navegador?')){data.pitches=data.pitches.filter(p=>p.id!==id);save();render()}if(b.dataset.copy){const text=`${p.demo?'EXEMPLO FICTÍCIO\n':''}${p.title}\n${p.date} | ${p.topic} | ${p.status}\nFonte: ${p.source}\n${p.url}\n\nInformação: ${p.facts}\n\nInteresse público: ${p.interest}\n\nHipótese: ${p.angle}\n\nPerguntas:\n${p.questions}`;try{await navigator.clipboard.writeText(text);toast('Ficha copiada.')}catch{download(text,'pauta.txt','text/plain')}}};
$('sourceForm').onsubmit=e=>{e.preventDefault();const url=safeUrl($('sourceUrl').value);if(!url){toast('Use um endereço http ou https.');return}data.sources.push({name:$('sourceName').value.trim(),url});save();e.target.reset();render();toast('Fonte adicionada.')};
$('guide').onclick=()=>{const questions=['O que mudou e qual é a evidência original?','Quem é afetado e quantas pessoas estão envolvidas?','Qual é o prazo e quem responde pela decisão?','Há orçamento ou recursos públicos envolvidos?','Que outra fonte pode confirmar ou contestar a informação?'];$('questions').value=[$('questions').value,...questions].filter(Boolean).join('\n');toast('Roteiro editorial adicionado. Adapte à pauta; não é análise por IA.')};
function download(text,name,type){const u=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
$('export').onclick=()=>download(JSON.stringify({exportedAt:new Date().toISOString(),...data},null,2),'radar-pautas.json','application/json');$('query').oninput=render;$('filter').onchange=render;$('cancel').onclick=()=>{reset();tab('board')};
$('demo').onclick=()=>{if(data.pitches.some(p=>p.id==='demo')){toast('O exemplo já está na lista.');return}data.pitches.unshift({id:'demo',demo:true,title:'Exemplo fictício: uma mudança em um serviço público',topic:'Cidade e serviços',source:'Material fictício da oficina',url:'',date:new Date().toISOString().slice(0,10),status:'Pista',facts:'Imagine que um comunicado anuncie novos horários de atendimento. Este exemplo não descreve um fato ocorrido no Cabo.',interest:'Entender quem depende do serviço e como a mudança afeta a rotina.',angle:'Verificar se a mudança resolve ou cria dificuldades para os moradores.',questions:'Qual é o motivo da mudança?\nComo os usuários foram informados?\nQuem pode apresentar uma experiência diferente?'});save();render();toast('Exemplo fictício adicionado.')};render();if(!persistence)toast('Armazenamento indisponível. Use Exportar JSON para guardar dados.');
